CALCULATE(
    SUM('Dim_Employee_Cost'[Monthly Cost]),

    // 1. ????????????????????????????? (Blank) ????????????????????????????
    FILTER(
        VALUES('Dim_Department'[Department_Group]),
        NOT(ISBLANK('Dim_Department'[Department_Group]))
    ),

    // 2. ???????????????????? (? ??? KEEPFILTERS ?????????????????????/??????)
    KEEPFILTERS(
        FILTER(
            'Dim_Employee_Cost',
            // ????????????????????????????????????
            VAR _QuitDate = RELATED('Dim_Employee'[Quit Date])
            RETURN
            // ????????: ??????????? (Blank) ???? ????????? Cost ???????? ???? "???????????????????" ???????????
            ISBLANK(_QuitDate) || 'Dim_Employee_Cost'[Cost Date] <= _QuitDate
        )
    )
)

CALCULATE(
    DISTINCTCOUNT('Dim_Employee_Cost'[Employee No]),
    FILTER(
        'Dim_Employee_Cost',
        // ????????????????????????????????????????????????? Cost
        VAR _QuitDate = RELATED('Dim_Employee'[Quit Date])
        RETURN
        // ??????????????????????? ???? ???????? Cost ???????????????????????????????
        ISBLANK(_QuitDate) || 'Dim_Employee_Cost'[Cost Date] <= _QuitDate
    )
)

// 1. ??????????????????????????????? P&L (??????? Blank ???)
VAR ValidDepts = 
    FILTER(
        VALUES('Dim_Department'[Department_Group]),
        NOT(ISBLANK('Dim_Department'[Department_Group])) && NOT(ISBLANK([Total Profit YTD]))
    )

// 2. ??????????????? "??????" (??? Profit ?????)
VAR LossCount = 
    COUNTROWS(
        FILTER(
            ValidDepts,
            [Total Profit YTD] < 0
        )
    )

// 3. ???????????????????
VAR TotalCount = COUNTROWS(ValidDepts)

// 4. ??????????????????????????????????? "X / Y"
RETURN
COALESCE(LossCount, 0) & " / " & COALESCE(TotalCount, 0)

// 1. ?????????????????????????????????????
VAR MaxProfit = MAXX(VALUES('Dim_Date'[ShortMonth]), [Total Profit])

// 2. ??????????????????????????????????????????
VAR BestMonthName = 
    CALCULATE(
        MAX('Dim_Date'[ShortMonth]),
        FILTER(VALUES('Dim_Date'[ShortMonth]), [Total Profit] = MaxProfit)
    )

// 3. ????????????????????????? (M) ????????????????? +/-
VAR FormattedProfit = 
    IF(MaxProfit > 0, "+", "") & FORMAT(MaxProfit / 1000000, "0.00") & "M"

// 4. ??????????????????????????
RETURN
BestMonthName & " " & FormattedProfit

// 1. ????????????? (??????? Filter ?????)
VAR FullYearProfit = 
    CALCULATE(
        [Total Profit], 
        REMOVEFILTERS('Dim_Date'[ShortMonth]) // ??? Filter ??????????????????????
    )

// 2. ?????????????? M
RETURN
IF(FullYearProfit > 0, "+", "") & FORMAT(FullYearProfit / 1000000, "0.00") & "M"
